	@Test
	void sharedSourceRowsPreserveAliasesFullWidthCoordinatesAndBackwardsReads() {
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_000_000L, 1_000_000L);
		int[] outputs = { 0, 1, 2, 3, 0, -1 };
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery();
				KernelResultCoordinates coordinates = KernelResultCoordinates.open(ledger, 4, outputs,
						new int[] { 0, 1, 2, 3, 4, -1 }, 15L, 64, 0, Transport.valueOf("ROWS"))) {
			assertThat(coordinates).isNotNull();
			long namespace = coordinates.newNamespace();
			long group = (1L << 42) + 3L;
			long parent = (1L << 44) + 5L;
			for (int row = 0; row < 64; row++) {
				for (int column = 0; column < 4; column++) {
					coordinates.set(column, group, parent, (1L << 35) + row / 4,
							(1L << 38) + column, namespace);
				}
				coordinates.emit();
			}
			assertThat(coordinates.enabled()).isTrue();
			coordinates.clearMask(-1L);
			coordinates.requestRetirement(namespace);
			List<Long> retired = new ArrayList<>();
			long[] copied = new long[KernelResultCoordinates.WIDTH];
			for (int ordinal = 0; ordinal < 64; ordinal++) {
				int row = ordinal * 37 & 63;
				for (int output = 0; output < outputs.length; output++) {
					assertThat(coordinates.coordinate(row, output, copied)).isEqualTo(outputs[output] >= 0);
					if (outputs[output] >= 0) {
						assertThat(copied).containsExactly(group, parent, (1L << 35) + row / 4,
								(1L << 38) + outputs[output], namespace);
					}
				}
				coordinates.releaseRow(row);
				assertThat(coordinates.hasCoordinate(row, 0)).isFalse();
				coordinates.drainRetiredNamespaces(retired::add);
				assertThat(retired).hasSize(ordinal == 63 ? 1 : 0);
			}
			assertThat(retired).containsExactly(namespace);
		}
		assertThat(manager.usedBytes()).isZero();
	}

