				coordinates.set(0, 11L, 100L, row / 4, 7L, first);
				coordinates.set(1, 11L, 100L, row / 4, 9L, first);
				coordinates.set(2, 22L, 200L, row % 4, 5L, second);
				coordinates.set(3, 22L, 200L, row % 4, 6L, second);
