				assertThat(coordinates.coordinate(row, 4, copied)).isTrue();
				assertThat(copied).containsExactly(11L, 100L, row / 4, 7L, first);
				assertThat(coordinates.coordinate(row, 3, copied)).isTrue();
				assertThat(copied).containsExactly(22L, 200L, row % 4, 6L, second);
