		assertThat(after.rowSelectionRows() - before.rowSelectionRows()).isEqualTo(32L);
		assertThat(after.rowSelectionColumns() - before.rowSelectionColumns()).isEqualTo(5L);
		assertThat(after.rowSelectionGroups() - before.rowSelectionGroups()).isEqualTo(2L);
