	@Test
	void earlyClosePublishesOnceAndReleasesFramesSidecarsAndBufferedRows() {
		Diagnostics before = KernelResultCoordinates.diagnostics();
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1_000_000L, 1_000_000L);
		try (LmdbQueryMemoryManager.QueryLedger ledger = manager.openQuery()) {
			KernelResultCoordinates coordinates = KernelResultCoordinates.open(ledger, 2,
					new int[] { 0, 1 }, new int[] { 0, 1 }, 3L, 8, 1, Transport.valueOf("ROWS"));
			long namespace = coordinates.newNamespace();
			coordinates.set(0, 1L, 2L, 3L, 0L, namespace);
			coordinates.set(1, 1L, 2L, 3L, 1L, namespace);
			coordinates.save(coordinates.newFrame());
			long[] sidecar = coordinates.newSourceBatch(1);
			assertThat(sidecar).isNotNull();
			sidecar[KernelResultCoordinates.NAMESPACE] = namespace;
			coordinates.retainBatch(sidecar, 1);
			coordinates.emit();
			coordinates.emit();
			long[] retained = new long[KernelResultCoordinates.WIDTH];
			assertThat(coordinates.coordinate(0, 1, retained)).isTrue();
			coordinates.close();
			assertThat(ledger.usedBytes()).isZero();
			assertThat(retained).containsExactly(1L, 2L, 3L, 1L, namespace);
			Diagnostics closed = KernelResultCoordinates.diagnostics();
			coordinates.close();
			assertThat(KernelResultCoordinates.diagnostics()).isEqualTo(closed);
		}
		Diagnostics after = KernelResultCoordinates.diagnostics();
		assertThat(after.rowSelectionOwners() - before.rowSelectionOwners()).isEqualTo(1L);
		assertThat(after.rowSelectionWindows() - before.rowSelectionWindows()).isEqualTo(1L);
		assertThat(after.rowSelectionRows() - before.rowSelectionRows()).isEqualTo(2L);
		assertThat(manager.usedBytes()).isZero();
	}

